<?php

declare(strict_types=1);

namespace App\Calls\Assignments;

use App\Contracts\Domains\CallSender;
use App\Data\Assignments\AssignmentResultData;
use App\Data\Assignments\AutoAssignmentChangeData;
use App\Data\Assignments\AutoAssignmentPageData;
use App\Data\Assignments\AutoAssignmentStatusData;
use App\Data\Assignments\RecordHolderData;
use App\Support\CallKey;

/**
 * The signed calls of Assignments, generated by php artisan journal:calls; run it again instead of editing.
 */
final readonly class AssignmentCalls
{
    public function __construct(private CallSender $sender) {}

    public function assignRecord(
        string $recordType,
        string $recordId,
        string $recipientType,
        string $recipientId,
        CallKey $requestKey = new CallKey(),
    ): AssignmentResultData {
        return $this->sender->send(AssignRecordCall::from([
            'recordType' => $recordType,
            'recordId' => $recordId,
            'recipientType' => $recipientType,
            'recipientId' => $recipientId,
            'requestKey' => $requestKey,
        ]));
    }

    /**
     * @param  list<string>  $records
     */
    public function configureAutoAssignment(
        string $actorType,
        string $actorId,
        string $assignableType,
        string $pool,
        array $records,
        int $size,
        int $expectedRevision,
        string|null $target,
        CallKey $requestKey = new CallKey(),
    ): AutoAssignmentChangeData {
        return $this->sender->send(ConfigureAutoAssignmentCall::from([
            'actorType' => $actorType,
            'actorId' => $actorId,
            'assignableType' => $assignableType,
            'pool' => $pool,
            'records' => $records,
            'size' => $size,
            'expectedRevision' => $expectedRevision,
            'target' => $target,
            'requestKey' => $requestKey,
        ]));
    }

    public function disableAutoAssignment(
        string $actorType,
        string $actorId,
        string $assignableType,
        int $expectedRevision,
        CallKey $requestKey = new CallKey(),
    ): AutoAssignmentChangeData {
        return $this->sender->send(DisableAutoAssignmentCall::from([
            'actorType' => $actorType,
            'actorId' => $actorId,
            'assignableType' => $assignableType,
            'expectedRevision' => $expectedRevision,
            'requestKey' => $requestKey,
        ]));
    }

    /**
     * @param  list<string>  $records
     */
    public function enableAutoAssignment(
        string $actorType,
        string $actorId,
        string $assignableType,
        string $pool,
        array $records,
        int $size,
        int $expectedRevision,
        string|null $target,
        CallKey $requestKey = new CallKey(),
    ): AutoAssignmentChangeData {
        return $this->sender->send(EnableAutoAssignmentCall::from([
            'actorType' => $actorType,
            'actorId' => $actorId,
            'assignableType' => $assignableType,
            'pool' => $pool,
            'records' => $records,
            'size' => $size,
            'expectedRevision' => $expectedRevision,
            'target' => $target,
            'requestKey' => $requestKey,
        ]));
    }

    public function listAssignmentPools(
        string $assignableType,
    ): PoolList {
        return $this->sender->send(ListAssignmentPoolsCall::from([
            'assignableType' => $assignableType,
        ]));
    }

    public function listAutoAssignments(
        string $actorType,
        string $actorId,
        string|null $after = null,
    ): AutoAssignmentPageData {
        return $this->sender->send(ListAutoAssignmentsCall::from([
            'actorType' => $actorType,
            'actorId' => $actorId,
            'after' => $after,
        ]));
    }

    public function reassignRecord(
        string $recordType,
        string $recordId,
        string $assignmentId,
        string $holderType,
        string $holderId,
        string $recipientType,
        string $recipientId,
        CallKey $requestKey = new CallKey(),
    ): AssignmentResultData {
        return $this->sender->send(ReassignRecordCall::from([
            'recordType' => $recordType,
            'recordId' => $recordId,
            'assignmentId' => $assignmentId,
            'holderType' => $holderType,
            'holderId' => $holderId,
            'recipientType' => $recipientType,
            'recipientId' => $recipientId,
            'requestKey' => $requestKey,
        ]));
    }

    public function showAssignment(
        string $recordType,
        string $recordId,
    ): RecordHolderData {
        return $this->sender->send(ShowAssignmentCall::from([
            'recordType' => $recordType,
            'recordId' => $recordId,
        ]));
    }

    public function showAutoAssignment(
        string $actorType,
        string $actorId,
        string $assignableType,
    ): AutoAssignmentStatusData {
        return $this->sender->send(ShowAutoAssignmentCall::from([
            'actorType' => $actorType,
            'actorId' => $actorId,
            'assignableType' => $assignableType,
        ]));
    }

    public function unassignRecord(
        string $recordType,
        string $recordId,
        string $assignmentId,
        string $holderType,
        string $holderId,
        CallKey $requestKey = new CallKey(),
    ): AssignmentResultData {
        return $this->sender->send(UnassignRecordCall::from([
            'recordType' => $recordType,
            'recordId' => $recordId,
            'assignmentId' => $assignmentId,
            'holderType' => $holderType,
            'holderId' => $holderId,
            'requestKey' => $requestKey,
        ]));
    }
}
